ST.xhtml:p:
(*送料轴点动*)
IF bJogFast THEN
  Feeding_Jog.Mode := 1;
ELSE
  Feeding_Jog.Mode := 0;
END_IF;

Feeding_Jog.JogForward := bFeedingJogForward;
Feeding_Jog.JogBackwards := bFeedingBackForward;
g_noerrorid := Feeding_Jog.errorid;
g_noerrorid := Feeding_Jog.errorid;
(*定长轴点动*)
IF bJogFast THEN
  FixedLen_Jog.Mode := 1;
ELSE
  FixedLen_Jog.Mode := 0;
END_IF;

FixedLen_Jog.JogForward := bFixedLenJogForward;
FixedLen_Jog.JogBackwards := bFixedLenBackForward;

(*抽尘轴点动*)
IF bJogFast THEN
  Dust_Jog.Mode := 1;
ELSE
  Dust_Jog.Mode := 0;
END_IF;

Dust_Jog.JogForward := bDustJogForward;
Dust_Jog.JogBackwards := bDustBackForward;


IF g_bPlcResetBuffer THEN
  bDustJogForward := FALSE;
  bDustBackForward := FALSE;
  bFixedLenJogForward := FALSE;
  bFixedLenBackForward := FALSE;
  bFeedingJogForward := FALSE;
  bFeedingBackForward := FALSE; 
END_IF;
